# mini_gpt.py：零第三方库，把字模、记账数字和注意力拼成迷你大脑
import math, random

texts = [
    "新同事先申请账号",
    "新同事先申请权限",
    "新同事先安装软件",
    "账号开通再安装软件",
]
chars = ["^", "$"] + sorted({c for t in texts for c in t})
stoi = {c: i for i, c in enumerate(chars)}
itos = {i: c for c, i in stoi.items()}
V, D = len(chars), 8

class Value:
    def __init__(self, data, prev=(), local_grads=()):
        self.data, self.grad = data, 0.0
        self._prev, self._lg = prev, local_grads
    def __add__(self, o):
        o = o if isinstance(o, Value) else Value(o)
        return Value(self.data + o.data, (self, o), (1.0, 1.0))
    def __radd__(self, o): return self + o
    def __mul__(self, o):
        o = o if isinstance(o, Value) else Value(o)
        return Value(self.data * o.data, (self, o), (o.data, self.data))
    def __rmul__(self, o): return self * o
    def __sub__(self, o): return self + (o * -1.0)
    def __truediv__(self, o): return self * (o ** -1.0)
    def __pow__(self, p): return Value(self.data ** p, (self,), (p * (self.data ** (p - 1)),))
    def exp(self):
        e = math.exp(max(-20, min(20, self.data)))
        return Value(e, (self,), (e,))
    def log(self):
        return Value(math.log(max(self.data, 1e-12)), (self,), (1.0 / max(self.data, 1e-12),))
    def relu(self):
        return Value(max(0.0, self.data), (self,), (1.0 if self.data > 0 else 0.0,))
    def backward(self):
        topo, seen = [], set()
        def build(v):
            if v not in seen:
                seen.add(v)
                for c in v._prev: build(c)
                topo.append(v)
        build(self)
        self.grad = 1.0
        for v in reversed(topo):
            for c, g in zip(v._prev, v._lg):
                c.grad += g * v.grad

rng = random.Random(42)
mat = lambda r, c: [[Value(rng.gauss(0, 0.2)) for _ in range(c)] for _ in range(r)]
wte, wpe = mat(V, D), mat(12, D)                       # 字向量表 + 位置向量表
wq, wk, wv, wo = mat(D, D), mat(D, D), mat(D, D), mat(D, V)
params = [p for m in (wte, wpe, wq, wk, wv, wo) for row in m for p in row]

def linear(x, w):
    return [sum(x[i] * w[i][j] for i in range(len(x))) for j in range(len(w[0]))]

def softmax(logits):
    m = max(l.data for l in logits)
    exps = [(l - m).exp() for l in logits]
    s = sum(exps)
    return [e / s for e in exps]

def step_gpt(tok_id, pos_id, keys, vals):
    x = [wte[tok_id][i] + wpe[pos_id][i] for i in range(D)]
    q, k, v = linear(x, wq), linear(x, wk), linear(x, wv)
    keys.append(k); vals.append(v)                     # 只留前面看过的字（因果遮罩）
    scores = [sum(q[i] * kj[i] for i in range(D)) * (D ** -0.5) for kj in keys]
    attn = softmax(scores)
    ctx = [sum(attn[t] * vals[t][i] for t in range(len(vals))) for i in range(D)]
    h = [x[i] + ctx[i].relu() for i in range(D)]
    return linear(h, wo)

print(f"词表大小 {V} 个，参数一共 {len(params)} 个")
for epoch in range(1, 81):
    total_loss = 0.0
    for text in texts:
        ids = [stoi[c] for c in ("^" + text + "$")]
        keys, vals, losses = [], [], []
        for pos, (cur, nxt) in enumerate(zip(ids, ids[1:])):
            probs = softmax(step_gpt(cur, pos, keys, vals))
            losses.append(probs[nxt].log() * -1.0)
        loss = sum(losses) * (1.0 / len(losses))
        for p in params: p.grad = 0.0
        loss.backward()
        for p in params: p.data -= 0.08 * p.grad
        total_loss += loss.data
    if epoch in (1, 20, 80):
        print(f"第 {epoch:2d} 轮，平均猜错代价（loss）：{total_loss / len(texts):.2f}")

for _ in range(3):
    cur, keys, vals, out = stoi["^"], [], [], []
    for pos in range(10):
        probs = softmax(step_gpt(cur, pos, keys, vals))
        cur = rng.choices(range(V), weights=[p.data for p in probs])[0]
        if cur == stoi["$"]: break
        out.append(itos[cur])
    print("它接出来的话：", "".join(out))

