# perceptron.py：一张会自己改的评分表
data = [(0, 0), (0, 1), (1, 0), (1, 1)]

def train(labels, rounds=20, show=False):
    w1 = w2 = b = 0                       # 一开始，它什么都不知道
    for r in range(1, rounds + 1):
        wrong = 0
        for (x1, x2), want in zip(data, labels):
            got = 1 if w1 * x1 + w2 * x2 + b >= 0 else 0
            miss = want - got             # 答对是 0；该说 1 却说 0 是 +1；反过来是 -1
            if miss:
                wrong += 1
                w1 += miss * x1           # 朝着纠正这次错误的方向，各挪一点
                w2 += miss * x2
                b += miss
        if show:
            print(f"第 {r} 轮：错 {wrong} 题，现在 w1={w1} w2={w2} b={b}")
        if wrong == 0:
            break
    return w1, w2, b, wrong

if __name__ == "__main__":
    print("教它：两样都办完，才能开通（AND）")
    train([0, 0, 0, 1], show=True)

